/*
 * A157455  Number generated by regarding the numbers in row n of A157454 as
 *          digits of a base n number.
 * https://oeis.org/A157455
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = FromDigits[{Table[Min[2*m-1, 2*(n-m)+1], {m,1,n}]}, n]
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 10, u64 n <= 16, u128 n <= 18,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;          /* out of offset – arbitrary */
    seq_t result = 0;
    const seq_t base = (seq_t)n;
    const idx_t mid = (n + 1) / 2;          /* first half threshold */

    for (idx_t m = 1; m <= n; ++m)
    {
        seq_t digit;
        if (m <= mid)
            digit = 2 * (seq_t)m - 1;
        else
            digit = 2 * (seq_t)(n - m) + 1;
        result = result * base + digit;
    }
    return result;
}
